/**
 *
 * @param type 'LOCALE_CHANGE' | 'TRANSLATIONS_CHANGE'
 */
function fireI18nChangeEvent(type) {
    const i18n = getI18nObject();
    for (const callback of i18n.updateCallbacks) {
        try {
            //Wrapped in a try catch block just in case there are errors
            //We still need to update the rest and we don't want to crash
            //the frontend application just because someone forgot to remove their change listener.
            callback(type);
        }
        catch (e) {
            console.error(e);
        }
    }
}
/**
 *
 * @param callback A Callback function that will be called whenever the message translations change.
 * @returns An unsubscribe function.
 */
export function addTranslationListener(callback) {
    return addUpdateListener(callback, 'TRANSLATIONS_CHANGE');
}
export function addLocalListener(callback) {
    return addUpdateListener(callback, 'LOCALE_CHANGE');
}
function addUpdateListener(callback, type) {
    const i18n = getI18nObject();
    const callbackWrapper = (callbackType) => {
        if (callbackType == null || callbackType === type) {
            callback();
        }
    };
    i18n.updateCallbacks.push(callbackWrapper);
    return () => {
        const index = i18n.updateCallbacks.indexOf(callbackWrapper);
        if (index >= 0) {
            i18n.updateCallbacks.splice(index, 1);
        }
    };
}
