// time = HH:mm | HH:mm:ss | hh:mm a | hh:mm:ss a
export function deLocalizeTime(time) {
    if (time == null) {
        return;
    }
    const locale = getCurrentLocale();
    let hours;
    let minutes;
    let seconds;
    let timeTokens;
    if (locale.DATETIME_FORMATS.shortTime.endsWith('a')) {
        //AM PM time
        timeTokens = AM_PM_TIME_REGEX.exec(time);
        if (timeTokens == null || timeTokens.length < 6 || !isLocalizedAmPm(timeTokens[5])) {
            return;
        }
        hours = Number(timeTokens[1]);
        minutes = Number(timeTokens[2]);
        seconds = Number(timeTokens[3]);
        if (isLocalizedPm(timeTokens[5])) {
            if (hours < 12) {
                hours += 12;
            }
        }
        else {
            // AM
            if (hours === 12) {
                hours = 0;
            }
        }
    }
    else {
        //24 hour time
        return parse24HourTime(time);
    }
    return new SimpleTime(hours, minutes, seconds);
}
export function parse24HourTime(time) {
    if (time == null) {
        return;
    }
    const timeTokens = time.split(':');
    // Tokens should be the hours and minutes, with optional seconds
    if (timeTokens.length < 2 || timeTokens.length > 3) {
        return;
    }
    const hours = Number(timeTokens[0]);
    const minutes = Number(timeTokens[1]);
    const seconds = Number(timeTokens[2] || '0');
    if (isNaN(hours) || isNaN(minutes) || isNaN(seconds)) {
        return;
    }
    return new SimpleTime(hours, minutes, seconds);
}
export function isValidTime(localizedTime) {
    const locale = getCurrentLocale();
    const show24Hours = locale.DATETIME_FORMATS.shortTime.toLowerCase() === 'hh:mm' || locale.DATETIME_FORMATS.shortTime.toLowerCase() === 'hh:mm:ss';
    if (show24Hours) {
        return TWENTY_FOUR_HOUR_TIME_REGEX.test(localizedTime);
    }
    else {
        //parse the localizedTime into tokens by executing the regex.
        //When this regex returns a RexExpExecArray with length === 6, it validates that the time is in the correct format
        //except for the AM/PM form which will be validated below in the isLocalizedAmPm() function
        const result = AM_PM_TIME_REGEX.exec(localizedTime);
        //result == null means the entire regex failed.
        //result.length > 5 is a guard to make sure we can access result[5]
        //result[5] contains what the user typed for the am/pm part so we ensure that it is a valid localized am/pm string.
        return result != null && result.length > 5 && isLocalizedAmPm(result[5]);
    }
}
//Returns true if the string matches the translated AM or PM tokens.
//Note: The comparison is done with all spaces stripped out and lowerCase.
//This allows the user to type in things like 'A m' and have it still work
function isLocalizedAmPm(amPmString) {
    return isLocalizedPm(amPmString) || isLocalizedAm(amPmString);
}
//Returns true if the string matches the translated PM token.
//Note: The comparison is done with all spaces stripped out and lowerCase.
//This allows the user to type in things like 'P m' and have it still work
function isLocalizedPm(pmString) {
    if (typeof pmString !== 'string') {
        return false;
    }
    return pmString.replace(/ /g, '').toLowerCase() === translate('mfe-utils|am-pm|PM').replace(/ /g, '').toLowerCase();
}
//Returns true if the string matches the translated AM token.
//Note: The comparison is done with all spaces stripped out and lowerCase.
//This allows the user to type in things like 'A m' and have it still work
function isLocalizedAm(pmString) {
    if (typeof pmString !== 'string') {
        return false;
    }
    return pmString.replace(/ /g, '').toLowerCase() === translate('mfe-utils|am-pm|AM').replace(/ /g, '').toLowerCase();
}
/**
 * Localize a number, and optionally round it to a specific number of decimal places
 * @param number, number to localize
 * @param decimalPlaces (optional), number of decimal places to round to
 * @param strictDecimals (optional), appends zeroes if number has fewer decimal places
 * @returns the localized version of the number
 */
export function localizeNumber(number, decimalPlaces, strictDecimals, useGroupSeparator) {
    if (number == null || isNaN(number)) {
        return;
    }
    const locale = getCurrentLocale();
    if (decimalPlaces != null && !isNaN(decimalPlaces)) {
        // round the number to n decimal places before localizing
        decimalPlaces = Math.abs(Math.floor(decimalPlaces));
        const multiplier = Math.pow(10, decimalPlaces);
        number = Math.round(number * multiplier) / multiplier;
    }
    let formattedNumber = String(number).replace('.', locale.NUMBER_FORMATS.DECIMAL_SEP);
    if (strictDecimals === true && decimalPlaces != null && !isNaN(decimalPlaces) && decimalPlaces > 0) {
        //Add zeroes and an appropriate decimal separator as padding to the localized number
        let numDecimals = 0;
        if (formattedNumber.includes(locale.NUMBER_FORMATS.DECIMAL_SEP)) {
            const parts = String(formattedNumber).split(locale.NUMBER_FORMATS.DECIMAL_SEP);
            numDecimals = parts[parts.length - 1].length;
        }
        if (numDecimals === 0) {
            formattedNumber = formattedNumber + locale.NUMBER_FORMATS.DECIMAL_SEP;
        }
        formattedNumber = formattedNumber + ('0').repeat(decimalPlaces - numDecimals);
    }
    if (useGroupSeparator && locale.NUMBER_FORMATS.GROUP_SEP.length > 0) {
        const [wholePart, decimalPart] = formattedNumber.split(locale.NUMBER_FORMATS.DECIMAL_SEP);
        formattedNumber = injectGroupSeparators(wholePart) + (decimalPart != null ? locale.NUMBER_FORMATS.DECIMAL_SEP + decimalPart : '');
    }
    return formattedNumber;
}
//The number must be a string of ONLY number characters, no decimal points
function injectGroupSeparators(number) {
    const locale = getCurrentLocale();
    const separatorLength = locale.NUMBER_FORMATS.number_format.indexOf(locale.NUMBER_FORMATS.DECIMAL_SEP) - locale.NUMBER_FORMATS.number_format.indexOf(locale.NUMBER_FORMATS.GROUP_SEP) - 1;
    let stringBuffer = '';
    let count = 0; //How many numeric characters we have added into the string buffer
    for (let i = number.length - 1; i >= 0; i--) {
        //First prepend the character
        stringBuffer = number[i] + stringBuffer;
        count++;
        //Now prepend the separatorChar if necessary
        if (count > 0 && count % separatorLength === 0 && i !== 0) {
            stringBuffer = locale.NUMBER_FORMATS.GROUP_SEP + stringBuffer;
        }
    }
    return stringBuffer;
}
export function deLocalizeNumber(numberString) {
    if (numberString == null) {
        return;
    }
    const locale = getCurrentLocale();
    const groupingSeparator = locale.NUMBER_FORMATS.GROUP_SEP;
    const decimalSeparator = locale.NUMBER_FORMATS.DECIMAL_SEP;
    const numericRegex = locale.NUMBER_FORMATS.number_regex;
    // IE does not like instantiating RegExp objects with empty values, so we have to
    // check for valid values in the grouping separator before using it in a RegExp.
    const gsNotBlank = (groupingSeparator === '.' || groupingSeparator === ',' || groupingSeparator === ' ');
    // We also want to check that only valid characters are present.
    const validNumber = new RegExp('^' + numericRegex + '$', 'g');
    if (numberString !== '' && numberString.match(validNumber) != null) {
        if (gsNotBlank) {
            const gs = new RegExp('\\' + groupingSeparator, 'g');
            numberString = numberString.replace(gs, '');
        }
        const ds = new RegExp('\\' + decimalSeparator, 'g'); //The decimal separator is not expected to be empty
        const number = parseFloat(numberString.replace(ds, '.'));
        if (!isNaN(number)) {
            return number;
        }
    }
}
export function isValidNumber(numValue) {
    if (numValue !== '') {
        const locale = getCurrentLocale();
        const regexString = '^' + locale.NUMBER_FORMATS.number_regex + '$';
        const regex = new RegExp(regexString, 'g');
        if (regex.test(numValue)) {
            return (deLocalizeNumber(numValue) != null);
        }
        else {
            return false;
        }
    }
    return false;
}
