/**
 * This is the function to format a time for display.
 */
export function formatTime(time, formatType) {
    if (time == null || formatType == null) {
        return '';
    }
    switch (formatType) {
        case 'TIME':
            return localizeTime(time, false);
        case 'TIME_PAD_ZEROS':
            return localizeTime(time, true);
        case 'TIME_COMPACT':
            return localizeTime(time, false, true);
        case 'TIME_SECONDS':
            return localizeTime(time, false, false, true);
        case 'TIME_SECONDS_PAD_ZEROS':
            return localizeTime(time, true, false, true);
        case 'TIME_SECONDS_COMPACT':
            return localizeTime(time, false, true, true);
        default:
            return localizeTime(time, false);
    }
}
