/**
 * This is the function to format a date for display.
 * @param date: The date object to format.
 * @param formatType: The format that you want to use.
 * @param isMidSentence: Set this to true if the output will be inserted in the middle of a sentence.
 */
export function formatDate(date, formatType, isMidSentence = false) {
    if (date == null) {
        return '';
    }
    switch (formatType) {
        case 'DATE_TIME':
            return translate('mfe-utils|date utils|xx at xx', {
                theDate: localizeDate(date),
                theTime: localizeTime(date)
            });
        case 'DATE_TIME_SR':
            return translate('mfe-utils|date utils|xx at xx', {
                theDate: localizeDatePretty(date, false, isMidSentence),
                theTime: localizeTime(date, false)
            });
        case 'DATE_TIME_PRETTY':
            return translate('mfe-utils|date utils|xx at xx', {
                theDate: localizeDatePretty(date, true, isMidSentence),
                theTime: localizeTime(date, false)
            });
        case 'DATE':
            return localizeDate(date);
        case 'DATE_SR':
            return localizeDatePretty(date, false, isMidSentence);
        case 'DATE_DAY_SHORT_MONTH':
            return dateDayShortMonth(date);
        case 'DATE_SHORT_MONTH':
            return dateShortMonth(date);
        case 'DATE_SHORT_DAY_SHORT_MONTH':
            return dateShortDayShortMonth(date);
        case 'DATE_PRETTY':
        default:
            return localizeDatePretty(date, true, isMidSentence);
    }
}
/**
 * Checks if the date format in the provided locale uses a "day before month" format.
 * This function checks the 'mediumDate' format in the locale to determine the format.
 * @param locale - The locale for which you want to check the date format.
 * @returns True if the format is "day before month," otherwise false.
 */
function isDayBeforeMonthFormat(locale) {
    return /d[^dm]*M/i.test(locale.DATETIME_FORMATS.mediumDate);
}
function dateDayShortMonth(date) {
    const locale = getCurrentLocale();
    const dayName = locale.DATETIME_FORMATS.DAY[date.getDay()];
    const day = date.getDate();
    const monthName = locale.DATETIME_FORMATS.SHORTMONTH[date.getMonth()];
    if (isDayBeforeMonthFormat(locale)) {
        return `${dayName}, ${day} ${monthName}`;
    }
    else {
        return `${dayName}, ${monthName} ${day}`;
    }
}
function dateShortMonth(date) {
    const locale = getCurrentLocale();
    const day = date.getDate();
    const monthName = locale.DATETIME_FORMATS.SHORTMONTH[date.getMonth()];
    if (isDayBeforeMonthFormat(locale)) {
        return `${day}, ${monthName}`;
    }
    else {
        return `${monthName}, ${day}`;
    }
}
function dateShortDayShortMonth(date) {
    const locale = getCurrentLocale();
    const day = date.getDate();
    const monthName = locale.DATETIME_FORMATS.SHORTMONTH[date.getMonth()];
    const dayName = locale.DATETIME_FORMATS.SHORTDAY[date.getDay()];
    if (isDayBeforeMonthFormat(locale)) {
        return `${dayName}, ${day} ${monthName}`;
    }
    else {
        return `${dayName}, ${monthName} ${day}`;
    }
}
